    public static string Panel() => """
<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#079b99"><title>NSX Veresiye Free Cloud</title>
<style>
:root{--pri:#079b99;--pri2:#087f8c;--ink:#162832;--muted:#6b7d88;--line:#dfe8ed;--bg:#f3f6f8;--card:#fff;--ok:#168653;--bad:#c54343;--shadow:0 10px 28px #18394412}*{box-sizing:border-box}body{margin:0;font-family:Segoe UI,system-ui,Arial,sans-serif;background:var(--bg);color:var(--ink)}button,input,select,textarea{font:inherit}button{cursor:pointer}.top{position:sticky;top:0;z-index:20;background:#fff;border-bottom:1px solid var(--line);padding:11px 14px}.topin{max-width:1080px;margin:auto;display:flex;align-items:center;gap:10px}.logo{width:42px;height:42px;border-radius:13px;background:linear-gradient(135deg,var(--pri),var(--pri2));color:#fff;display:grid;place-items:center;font-weight:900}.brand{min-width:0}.brand b{display:block;font-size:16px}.brand span{display:block;font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:360px}.grow{flex:1}.company-select{display:none;max-width:230px;border:1px solid var(--line);border-radius:11px;background:#fff;padding:9px 30px 9px 10px}.iconbtn{border:1px solid var(--line);background:#fff;border-radius:11px;width:40px;height:40px;color:#425963}.shell{max-width:1080px;margin:auto;padding:18px 14px 54px}.hero{display:flex;align-items:flex-end;gap:12px;margin-bottom:16px}.hero h1{font-size:24px;margin:0 0 4px}.hero p{margin:0;color:var(--muted)}.status{margin-left:auto;font-size:12px;color:var(--ok);background:#e9f7f1;padding:7px 10px;border-radius:999px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.card{background:var(--card);border:1px solid var(--line);border-radius:17px;padding:16px;box-shadow:var(--shadow)}.metric small{color:var(--muted);font-size:12px}.metric strong{display:block;font-size:24px;margin-top:7px}.metric em{display:block;font-style:normal;font-size:11px;color:var(--muted);margin-top:3px}.customer-panel{margin-top:14px}.panelhead{display:flex;align-items:center;gap:10px;margin-bottom:12px}.panelhead h2{font-size:19px;margin:0}.count{color:var(--muted);font-size:12px}.btn{border:0;border-radius:11px;padding:11px 15px;font-weight:750}.btn.pri{background:var(--pri);color:#fff}.btn.collect{background:#167f70;color:#fff}.btn.ghost{background:#eef3f5;color:#314952}.btn:disabled{opacity:.45;cursor:not-allowed}.search{width:100%;border:1px solid #cfdce3;background:#fff;border-radius:13px;padding:13px 14px;outline:none}.search:focus{border-color:#72c9c5;box-shadow:0 0 0 3px #079b9916}.searchhint{margin:8px 2px 0;color:var(--muted);font-size:11px}.customer-list{display:grid;gap:8px;margin-top:12px}.customer-item{width:100%;border:1px solid #e1eaee;background:#fff;border-radius:14px;padding:12px 13px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;text-align:left;color:var(--ink)}.customer-item:hover{border-color:#a9d9d7;background:#f8fdfd}.customer-item.active{border-color:#71c9c5;background:#effafa;box-shadow:inset 4px 0 0 var(--pri)}.customer-main b{display:block;font-size:14px}.customer-main span{display:block;margin-top:3px;color:var(--muted);font-size:12px}.customer-balance{text-align:right;align-self:center}.customer-balance small{display:block;color:var(--muted);font-size:10px}.customer-balance strong{display:block;margin-top:3px;font-size:14px}.bad{color:var(--bad)}.ok{color:var(--ok)}.empty{padding:24px;text-align:center;color:var(--muted);border:1px dashed #d6e1e6;border-radius:13px;background:#fafcfd}.ledger{margin-top:14px}.ledgerhead{display:flex;align-items:flex-start;gap:12px}.eyebrow{font-size:10px;font-weight:900;letter-spacing:.12em;color:var(--pri)}.ledgerhead h2{margin:3px 0 4px;font-size:22px}.ledgerhead p{margin:0;color:var(--muted)}.ledger-actions{margin-left:auto;display:flex;gap:8px;flex-wrap:wrap}.ledgerstats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:15px 0}.ledgerstats>div{background:#f7fafb;border:1px solid #e4ecef;border-radius:13px;padding:12px}.ledgerstats small{display:block;color:var(--muted);font-size:11px}.ledgerstats b{display:block;margin-top:5px;font-size:18px}.moves-title{font-size:15px;margin:4px 0 10px}.moves{display:grid;gap:7px}.move{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:center;border:1px solid #e5edf0;border-radius:12px;padding:10px 11px}.move-type{padding:5px 8px;border-radius:999px;font-size:10px;font-weight:850}.move-type.debt{background:#fff0ef;color:#b83f3f}.move-type.payment{background:#e8f7f0;color:#168653}.move-info b{display:block;font-size:12px}.move-info span{display:block;margin-top:3px;color:var(--muted);font-size:11px}.move-money{text-align:right}.move-money strong{display:block;font-size:13px}.move-money small{display:block;color:var(--muted);font-size:10px;margin-top:3px}.modal{position:fixed;z-index:50;inset:0;background:#10242d88;display:none;align-items:flex-end;justify-content:center}.modal.show{display:flex}.dialog{background:#fff;width:min(560px,100%);max-height:92vh;overflow:auto;border-radius:22px 22px 0 0;padding:20px}.dhead{display:flex;align-items:center}.dhead h3{margin:0;font-size:20px}.close{margin-left:auto;border:0;background:#eef3f5;width:36px;height:36px;border-radius:50%}.form{display:grid;gap:12px;margin-top:16px}.f{display:grid;gap:6px}.f label{font-size:12px;color:#637580;font-weight:700}.f input,.f select,.f textarea{width:100%;border:1px solid #cedce3;border-radius:11px;padding:11px;background:#fff}.f textarea{min-height:74px;resize:vertical}.fixedcustomer{display:flex;justify-content:space-between;gap:10px;align-items:center;border:1px solid #cfe4e3;background:#f2fbfa;border-radius:11px;padding:11px 12px}.fixedcustomer span{color:var(--muted);font-size:12px}.formhint{color:var(--muted);font-size:11px}.actions{display:flex;justify-content:flex-end;gap:9px;margin-top:18px}.toast{position:fixed;z-index:80;left:50%;bottom:24px;transform:translateX(-50%);background:#162832;color:#fff;padding:10px 15px;border-radius:999px;opacity:0;pointer-events:none;transition:.2s;max-width:92%;text-align:center}.toast.show{opacity:1}@media(max-width:720px){.brand span{max-width:170px}.shell{padding:14px 11px 42px}.hero{align-items:flex-start}.hero h1{font-size:20px}.status{display:none}.cards{grid-template-columns:1fr 1fr}.metric strong{font-size:20px}.panelhead{align-items:center;flex-wrap:wrap}.panelhead .btn{margin-left:auto}.ledgerhead{flex-wrap:wrap}.ledger-actions{margin-left:0;width:100%}.ledger-actions .btn{flex:1}.ledgerstats{grid-template-columns:1fr 1fr}.ledgerstats>div:last-child{grid-column:1/-1}.move{grid-template-columns:auto minmax(0,1fr)}.move-money{grid-column:2;text-align:left}.company-select{max-width:130px}}@media(max-width:390px){.cards{gap:8px}.card{padding:13px}.brand b{font-size:13px}.brand span{max-width:120px}.iconbtn{width:37px;height:37px}.company-select{max-width:105px}}
</style></head><body>
<header class="top"><div class="topin"><div class="logo">NSX</div><div class="brand"><b>Veresiye Free Cloud</b><span id="tenantName">Mobil cari y&ouml;netim</span></div><div class="grow"></div><select class="company-select" id="companySelect" title="Firma se&ccedil;"></select><button class="iconbtn" id="refreshBtn" title="Yenile">&#8635;</button><button class="iconbtn" id="logoutBtn" title="&Ccedil;&#305;k&#305;&#351;">&#9099;</button></div></header>
<main class="shell"><section class="hero"><div><h1>Cari Y&ouml;netim</h1><p>M&uuml;&#351;terinizi bulun, cari hareketlerini g&ouml;r&uuml;n ve i&#351;leminizi yap&#305;n.</p></div><div class="status" id="syncState">&#9679; Cloud ba&#287;l&#305;</div></section><div class="cards" id="metrics"></div><section class="card customer-panel"><div class="panelhead"><h2>M&uuml;&#351;teri Ara</h2><span class="count" id="customerCount"></span><button class="btn pri" id="newCustomerBtn">+ Yeni M&uuml;&#351;teri Ekle</button></div><input class="search" id="searchBox" type="search" autocomplete="off" placeholder="Ad soyad, telefon veya barkod yaz&#305;n"><div class="searchhint" id="searchHint"></div><div class="customer-list" id="customerList"></div></section><div id="customerLedger"></div></main>
<div class="modal" id="modal"><div class="dialog"><div class="dhead"><h3 id="modalTitle">Kay&#305;t</h3><button class="close" id="closeModal">&times;</button></div><form id="editForm"><div class="form" id="formFields"></div><div class="actions"><button type="button" class="btn ghost" id="cancelBtn">Vazge&ccedil;</button><button type="submit" class="btn pri" id="saveBtn">Kaydet</button></div></form></div></div><div class="toast" id="toast"></div>
<script>
const state={csrf:'',company:'',selectedCustomerId:'',customerQuery:'',editing:'',lastChangeId:0,liveBusy:false,data:{companies:[],customers:[],debts:[],payments:[]}};
const $=id=>document.getElementById(id),money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(Number(v)||0),date=v=>{if(!v)return'-';const d=new Date(v);return isNaN(d)?String(v):d.toLocaleString('tr-TR',{dateStyle:'short',timeStyle:'short'})},num=v=>Number(String(v??'').replace(',','.'))||0,esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function parseItems(items){return(items||[]).map(x=>{let p={};try{p=JSON.parse(x.payloadJson||x.PayloadJson||'{}')}catch{};return{...p,__id:x.id||x.Id,__company:x.companyCloudId||x.CompanyCloudId||p.CompanyCloudId||''}})}
function companyId(x){return x.CompanyCloudId||x.__company||''}function selected(arr){return state.company?arr.filter(x=>companyId(x)===state.company||x.__id===state.company):arr}function norm(v){return String(v??'').toLocaleLowerCase('tr-TR').replace(/\s+/g,' ').trim()}function customerText(c){return norm([c?.FullName,c?.Phone,c?.BarcodeNo].join(' '))}
function paymentDebt(p){return state.data.debts.find(d=>d.__id===(p.DebtCloudId||''))}function paymentCustomerId(p){return p.CustomerCloudId||paymentDebt(p)?.CustomerCloudId||''}function customerDebts(id){return selected(state.data.debts).filter(d=>d.CustomerCloudId===id)}function customerPayments(id){return selected(state.data.payments).filter(p=>paymentCustomerId(p)===id)}function debtPayments(d){return state.data.payments.filter(p=>p.DebtCloudId===d.__id)}function debtPaid(d){const rows=debtPayments(d);return rows.length?rows.reduce((a,p)=>a+num(p.Amount),0):num(d.PaidAmount)}function debtBalance(d){return num(d.TotalPrice)-debtPaid(d)}function customerBalance(id){const ds=customerDebts(id),debt=ds.reduce((a,d)=>a+num(d.TotalPrice),0),paid=ds.reduce((a,d)=>a+debtPaid(d),0);return debt-paid}
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json'};if(state.csrf&&opt.method&&opt.method!=='GET')opt.headers['X-NSX-CSRF']=state.csrf;const r=await fetch(url,opt);if(r.status===401){location.href='/VeresiyeFreeCloud';throw Error('Oturum sona erdi.')}let j={};try{j=await r.json()}catch{}if(!r.ok)throw Error(j.message||'İşlem tamamlanamadı.');return j}
async function load(show=true){if(show)$('syncState').textContent='\u25cf Yenileniyor';try{const j=await api('/api/veresiyefreecloud/mobile/bootstrap');state.csrf=j.csrfToken||'';state.lastChangeId=Number(j.lastChangeId)||0;$('tenantName').textContent=j.companyName||'NSX Veresiye';state.data.companies=parseItems(j.companies);state.data.customers=parseItems(j.customers);state.data.debts=parseItems(j.debts);state.data.payments=parseItems(j.payments);fillCompanies();render();$('syncState').textContent='\u25cf Cloud ba\u011fl\u0131'}catch(e){$('syncState').textContent='\u25cf Ba\u011flant\u0131 hatas\u0131';toast(e.message)}}
function fillCompanies(){const rows=state.data.companies,sel=$('companySelect'),old=state.company;if(!rows.length){state.company='';sel.style.display='none';return}state.company=rows.some(c=>c.__id===old)?old:rows[0].__id;sel.innerHTML=rows.map(c=>`<option value="${esc(c.__id)}">${esc(c.Name||'Firma')}</option>`).join('');sel.value=state.company;sel.style.display=rows.length>1?'block':'none'}
function metrics(){const ds=selected(state.data.debts),cs=selected(state.data.customers),debt=ds.reduce((a,d)=>a+num(d.TotalPrice),0),paid=ds.reduce((a,d)=>a+debtPaid(d),0);return{debt,paid,balance:Math.max(0,debt-paid),customers:cs.length}}function metric(label,value,sub){return`<div class="card metric"><small>${label}</small><strong>${value}</strong><em>${sub}</em></div>`}
function render(){const m=metrics();$('metrics').innerHTML=metric('Toplam Bor&ccedil;',money(m.debt),'T&uuml;m cari bor&ccedil;lar')+metric('Toplam Tahsilat',money(m.paid),'Al&#305;nan tahsilatlar')+metric('A&ccedil;&#305;k Bakiye',money(m.balance),'Toplam a&ccedil;&#305;k bakiye');renderCustomerList();renderLedger()}
function customerRows(){const all=selected(state.data.customers).sort((a,b)=>String(a.FullName||'').localeCompare(String(b.FullName||''),'tr')),q=norm(state.customerQuery),filtered=q?all.filter(c=>customerText(c).includes(q)):all,limit=q?120:60,shown=filtered.slice(0,limit);return{all,filtered,shown}}
function renderCustomerList(){const x=customerRows();$('customerCount').textContent=`${x.filtered.length} / ${x.all.length}`;$('searchHint').textContent=x.filtered.length>x.shown.length?`\u0130lk ${x.shown.length} kay\u0131t g\u00f6steriliyor. Aramay\u0131 daraltabilirsiniz.`:(state.customerQuery?'Arama sonucuna t\u0131klayarak cari hesab\u0131 a\u00e7\u0131n.':'M\u00fc\u015fteriye t\u0131klayarak cari hesab\u0131n\u0131 a\u00e7\u0131n.');$('customerList').innerHTML=x.shown.length?x.shown.map(c=>{const b=customerBalance(c.__id);return`<button type="button" class="customer-item ${state.selectedCustomerId===c.__id?'active':''}" data-customer-id="${esc(c.__id)}"><span class="customer-main"><b>${esc(c.FullName||'\u0130simsiz m\u00fc\u015fteri')}</b><span>${esc(c.Phone||c.BarcodeNo||'-')}</span></span><span class="customer-balance"><small>Cari Bakiye</small><strong class="${b>0?'bad':'ok'}">${money(b)}</strong></span></button>`}).join(''):'<div class="empty">M&uuml;&#351;teri bulunamad&#305;.</div>';document.querySelectorAll('[data-customer-id]').forEach(b=>b.onclick=()=>selectCustomer(b.dataset.customerId))}
function selectCustomer(id){state.selectedCustomerId=id;renderCustomerList();renderLedger();setTimeout(()=>$('customerLedger')?.scrollIntoView({behavior:'smooth',block:'start'}),30)}
function customerMovements(id){const rows=[];for(const d of customerDebts(id)){rows.push({type:'debt',date:d.CreatedAt,desc:d.Description||d.FaultDescription||'Bor\u00e7',debt:num(d.TotalPrice),payment:0});const ps=debtPayments(d);if(!ps.length&&num(d.PaidAmount)>0)rows.push({type:'payment',date:d.CreatedAt,desc:'Kay\u0131tl\u0131 tahsilat',debt:0,payment:num(d.PaidAmount)})}for(const p of customerPayments(id))rows.push({type:'payment',date:p.PaymentDate,desc:'Tahsilat',debt:0,payment:num(p.Amount)});rows.sort((a,b)=>new Date(a.date)-new Date(b.date));let balance=0;for(const r of rows){balance+=r.debt-r.payment;r.balance=balance}return rows.reverse()}
function renderLedger(){const box=$('customerLedger'),id=state.selectedCustomerId;if(!id){box.innerHTML='';return}const c=state.data.customers.find(x=>x.__id===id);if(!c){state.selectedCustomerId='';box.innerHTML='';return}const ds=customerDebts(id),totalDebt=ds.reduce((a,d)=>a+num(d.TotalPrice),0),totalPaid=ds.reduce((a,d)=>a+debtPaid(d),0),balance=totalDebt-totalPaid,moves=customerMovements(id);box.innerHTML=`<section class="card ledger"><div class="ledgerhead"><div><span class="eyebrow">CARI HESAP</span><h2>${esc(c.FullName||'M\u00fc\u015fteri')}</h2><p>${esc(c.Phone||c.BarcodeNo||'')}</p></div><div class="ledger-actions"><button class="btn pri" id="addDebtBtn">+ Bor&ccedil; Gir</button><button class="btn collect" id="addPaymentBtn" ${balance<=0.005?'disabled':''}>+ Tahsilat Yap</button></div></div><div class="ledgerstats"><div><small>Toplam Bor&ccedil;</small><b class="bad">${money(totalDebt)}</b></div><div><small>Toplam Tahsilat</small><b class="ok">${money(totalPaid)}</b></div><div><small>A&ccedil;&#305;k Bakiye</small><b class="${balance>0?'bad':'ok'}">${money(balance)}</b></div></div><h3 class="moves-title">Cari Hareketleri</h3><div class="moves">${moves.length?moves.map(r=>`<div class="move"><span class="move-type ${r.type}">${r.type==='debt'?'BOR\u00c7':'TAHS\u0130LAT'}</span><span class="move-info"><b>${esc(r.desc)}</b><span>${date(r.date)}</span></span><span class="move-money"><strong class="${r.type==='debt'?'bad':'ok'}">${r.type==='debt'?'+':'-'} ${money(r.type==='debt'?r.debt:r.payment)}</strong><small>Bakiye: ${money(r.balance)}</small></span></div>`).join(''):'<div class="empty">Hen&uuml;z cari hareket yok.</div>'}</div></section>`;$('addDebtBtn').onclick=()=>openEditor('debt');$('addPaymentBtn').onclick=()=>openEditor('payment')}
function fixedCustomer(c){return`<div class="f"><label>M&uuml;&#351;teri</label><div class="fixedcustomer"><b>${esc(c?.FullName||'-')}</b><span>${esc(c?.Phone||c?.BarcodeNo||'')}</span></div></div>`}function field(label,id,type='text',value='',extra=''){return`<div class="f"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`}function area(label,id,value=''){return`<div class="f"><label for="${id}">${label}</label><textarea id="${id}">${esc(value)}</textarea></div>`}
function openEditor(type){state.editing=type;const c=state.data.customers.find(x=>x.__id===state.selectedCustomerId);let h='';if(type==='customer'){$('modalTitle').textContent='Yeni M\u00fc\u015fteri Ekle';h=field('Ad Soyad','eName','text','','required maxlength="150" autocomplete="name"')+field('Telefon','ePhone','tel','','maxlength="30" autocomplete="tel"')}else{if(!c)return toast('\u00d6nce bir m\u00fc\u015fteri se\u00e7in.');if(type==='debt'){$('modalTitle').textContent='Bor\u00e7 Gir';h=fixedCustomer(c)+field('Bor\u00e7 Tutar\u0131','eAmount','number','','required min="0.01" step="0.01" inputmode="decimal"')+area('A\u00e7\u0131klama','eDesc','')}if(type==='payment'){const open=customerDebts(c.__id).filter(d=>debtBalance(d)>0.005).sort((a,b)=>new Date(a.CreatedAt)-new Date(b.CreatedAt));if(!open.length)return toast('Bu m\u00fc\u015fterinin a\u00e7\u0131k borcu yok.');$('modalTitle').textContent='Tahsilat Yap';h=fixedCustomer(c)+`<div class="f"><label for="eDebt">A\u00e7\u0131k Bor\u00e7</label><select id="eDebt">${open.map(d=>`<option value="${esc(d.__id)}">${esc(d.Description||d.FaultDescription||'Bor\u00e7')} - ${money(debtBalance(d))}</option>`).join('')}</select><div class="formhint" id="paymentLimit"></div></div>`+field('Tahsilat Tutar\u0131','eAmount','number','','required min="0.01" step="0.01" inputmode="decimal"')}}$('formFields').innerHTML=h;$('modal').classList.add('show');document.body.style.overflow='hidden';if(type==='payment'){const sel=$('eDebt');sel.onchange=updatePaymentLimit;updatePaymentLimit()}setTimeout(()=>$('eName')?.focus()||$('eAmount')?.focus(),40)}
function updatePaymentLimit(){const d=state.data.debts.find(x=>x.__id===$('eDebt')?.value),remaining=d?Math.max(0,debtBalance(d)):0;if($('paymentLimit'))$('paymentLimit').textContent=`Kalan bor\u00e7: ${money(remaining)}`;if($('eAmount'))$('eAmount').removeAttribute('max')}function guid(){return'WEB-'+Date.now().toString(36).toUpperCase()+'-'+crypto.getRandomValues(new Uint32Array(1))[0].toString(36).toUpperCase()}async function postEntity(type,id,payload){return api(`/api/veresiyefreecloud/mobile/data/${type}/${encodeURIComponent(id)}`,{method:'POST',body:JSON.stringify({payloadJson:JSON.stringify(payload)})})}
async function saveForm(e){e.preventDefault();const type=state.editing,now=new Date().toISOString();if(!type)return;if(!state.company)return toast('Firma verisi Cloud taraf\u0131na hen\u00fcz gelmedi.');$('saveBtn').disabled=true;try{if(type==='customer'){const name=$('eName').value.trim(),phone=$('ePhone').value.trim();if(!name)return toast('Ad soyad girin.');const id=guid();await postEntity('customer',id,{CloudId:id,CompanyCloudId:state.company,FullName:name,Phone:phone,BarcodeNo:'',Email:'',Address:'',CreatedAt:now});state.selectedCustomerId=id;state.customerQuery=''}else if(type==='debt'){const amount=num($('eAmount').value);if(amount<=0)return toast('Ge\u00e7erli bir bor\u00e7 tutar\u0131 girin.');const id=guid(),cid=state.selectedCustomerId,desc=$('eDesc').value.trim();await postEntity('debt',id,{CloudId:id,CompanyCloudId:state.company,CustomerCloudId:cid,ServiceNo:'WEB-'+Date.now(),Description:desc||'Bor\u00e7',FaultDescription:desc||'Bor\u00e7',DeviceType:'Bor\u00e7',Status:'A\u00e7\u0131k',TotalPrice:amount,PaidAmount:0,LaborPrice:0,PartPrice:0,Discount:0,IsDelivered:false,CreatedAt:now})}else if(type==='payment'){const debtId=$('eDebt').value,d=state.data.debts.find(x=>x.__id===debtId),amount=num($('eAmount').value);if(!d)return toast('A\u00e7\u0131k bor\u00e7 se\u00e7in.');if(amount<=0)return toast('Ge\u00e7erli bir tahsilat tutar\u0131 girin.');const id=guid();await postEntity('payment',id,{CloudId:id,CompanyCloudId:state.company,CustomerCloudId:state.selectedCustomerId,DebtCloudId:debtId,Amount:amount,PaymentType:'Nakit',Note:'Mobil tahsilat',PaymentDate:now})}closeModal();toast('\u0130\u015flem kaydedildi.');await load(false);setTimeout(()=>$('customerLedger')?.scrollIntoView({behavior:'smooth',block:'start'}),30)}catch(err){toast(err.message)}finally{if($('saveBtn'))$('saveBtn').disabled=false}}
function closeModal(){$('modal').classList.remove('show');document.body.style.overflow='';state.editing='';$('formFields').innerHTML=''}let toastTimer;function toast(s){const t=$('toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
$('searchBox').oninput=e=>{state.customerQuery=e.target.value;renderCustomerList()};$('newCustomerBtn').onclick=()=>openEditor('customer');$('companySelect').onchange=e=>{state.company=e.target.value;state.selectedCustomerId='';state.customerQuery='';$('searchBox').value='';render()};$('refreshBtn').onclick=()=>load();$('logoutBtn').onclick=async()=>{if(!confirm('Telefon oturumundan \u00e7\u0131k\u0131ls\u0131n m\u0131?'))return;await fetch('/VeresiyeFreeCloud/cikis',{method:'POST'});location.href='/VeresiyeFreeCloud'};$('closeModal').onclick=$('cancelBtn').onclick=closeModal;$('modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('editForm').onsubmit=saveForm;window.addEventListener('online',()=>{$('syncState').textContent='\u25cf Cloud ba\u011fl\u0131'});window.addEventListener('offline',()=>{$('syncState').textContent='\u25cf \u0130nternet yok'});async function checkLive(){if(state.liveBusy||document.hidden)return;state.liveBusy=true;try{const j=await api(`/api/veresiyefreecloud/mobile/sync/status?afterId=${state.lastChangeId}`);if(j.hasChanges||Number(j.lastChangeId)>state.lastChangeId)await load(false)}catch{}finally{state.liveBusy=false}}load();setInterval(checkLive,700);
</script></body></html>
""";

